-- HiredAF initial recruiting workspace schema. Applied to the connected Supabase project.
create extension if not exists pgcrypto;
create type public.member_role as enum ('owner','admin','recruiter','viewer');
create type public.job_status as enum ('draft','open','paused','closed');
create type public.application_status as enum ('new','reviewing','interview','offer','hired','rejected');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, avatar_url text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.organizations (id uuid primary key default gen_random_uuid(), name text not null check(char_length(trim(name)) between 2 and 120), created_by uuid not null references auth.users(id) on delete restrict, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.organization_members (organization_id uuid not null references public.organizations(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, role public.member_role not null default 'recruiter', created_at timestamptz not null default now(), primary key(organization_id,user_id));
create table public.jobs (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, title text not null check(char_length(trim(title)) between 2 and 160), department text, location text, employment_type text, description text, requirements text, status public.job_status not null default 'draft', created_by uuid not null references auth.users(id) on delete restrict, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.candidates (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, full_name text not null check(char_length(trim(full_name)) between 1 and 160), email text, phone text, location text, resume_url text, summary text, source text, created_by uuid not null references auth.users(id) on delete restrict, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,email));
create table public.applications (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, job_id uuid not null references public.jobs(id) on delete cascade, candidate_id uuid not null references public.candidates(id) on delete cascade, status public.application_status not null default 'new', rating smallint check(rating between 1 and 5), notes text, applied_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(job_id,candidate_id));
create table public.activity_events (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, actor_id uuid references auth.users(id) on delete set null, entity_type text not null, entity_id uuid, action text not null, details jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create index organization_members_user_idx on public.organization_members(user_id);
create index jobs_org_status_idx on public.jobs(organization_id,status);
create index candidates_org_created_idx on public.candidates(organization_id,created_at desc);
create index applications_org_status_idx on public.applications(organization_id,status);
create index applications_job_idx on public.applications(job_id);
create index activity_events_org_created_idx on public.activity_events(organization_id,created_at desc);
create function public.is_org_member(target_org uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.organization_members m where m.organization_id=target_org and m.user_id=(select auth.uid())); $$;
create function public.has_org_role(target_org uuid, allowed_roles public.member_role[]) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.organization_members m where m.organization_id=target_org and m.user_id=(select auth.uid()) and m.role=any(allowed_roles)); $$;
create function public.create_organization(org_name text) returns uuid language plpgsql security definer set search_path='' as $$
declare new_org_id uuid;
begin
 if auth.uid() is null then raise exception 'Sign in required'; end if;
 if char_length(trim(org_name))<2 or char_length(trim(org_name))>120 then raise exception 'Workspace name must be 2-120 characters'; end if;
 insert into public.organizations(name,created_by) values(trim(org_name),auth.uid()) returning id into new_org_id;
 insert into public.organization_members(organization_id,user_id,role) values(new_org_id,auth.uid(),'owner');
 return new_org_id;
end; $$;
create function public.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$
begin insert into public.profiles(id,full_name) values(new.id,nullif(new.raw_user_meta_data->>'full_name','')) on conflict(id) do nothing; return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
alter table public.profiles enable row level security;
alter table public.organizations enable row level security;
alter table public.organization_members enable row level security;
alter table public.jobs enable row level security;
alter table public.candidates enable row level security;
alter table public.applications enable row level security;
alter table public.activity_events enable row level security;
create policy "Users can read own profile" on public.profiles for select to authenticated using(id=(select auth.uid()));
create policy "Users can create own profile" on public.profiles for insert to authenticated with check(id=(select auth.uid()));
create policy "Users can update own profile" on public.profiles for update to authenticated using(id=(select auth.uid())) with check(id=(select auth.uid()));
create policy "Members can view organizations" on public.organizations for select to authenticated using(public.is_org_member(id));
create policy "Admins can update organizations" on public.organizations for update to authenticated using(public.has_org_role(id,array['owner','admin']::public.member_role[])) with check(public.has_org_role(id,array['owner','admin']::public.member_role[]));
create policy "Members can view membership" on public.organization_members for select to authenticated using(user_id=(select auth.uid()) or public.is_org_member(organization_id));
create policy "Admins can add members" on public.organization_members for insert to authenticated with check(public.has_org_role(organization_id,array['owner','admin']::public.member_role[]));
create policy "Admins can update members" on public.organization_members for update to authenticated using(public.has_org_role(organization_id,array['owner','admin']::public.member_role[])) with check(public.has_org_role(organization_id,array['owner','admin']::public.member_role[]));
create policy "Admins can remove members" on public.organization_members for delete to authenticated using(public.has_org_role(organization_id,array['owner','admin']::public.member_role[]));
create policy "Members can view jobs" on public.jobs for select to authenticated using(public.is_org_member(organization_id));
create policy "Recruiters can create jobs" on public.jobs for insert to authenticated with check(public.has_org_role(organization_id,array['owner','admin','recruiter']::public.member_role[]) and created_by=(select auth.uid()));
create policy "Recruiters can update jobs" on public.jobs for update to authenticated using(public.has_org_role(organization_id,array['owner','admin','recruiter']::public.member_role[])) with check(public.has_org_role(organization_id,array['owner','admin','recruiter']::public.member_role[]));
create policy "Admins can delete jobs" on public.jobs for delete to authenticated using(public.has_org_role(organization_id,array['owner','admin']::public.member_role[]));
create policy "Members can view candidates" on public.candidates for select to authenticated using(public.is_org_member(organization_id));
create policy "Recruiters can add candidates" on public.candidates for insert to authenticated with check(public.has_org_role(organization_id,array['owner','admin','recruiter']::public.member_role[]) and created_by=(select auth.uid()));
create policy "Recruiters can update candidates" on public.candidates for update to authenticated using(public.has_org_role(organization_id,array['owner','admin','recruiter']::public.member_role[])) with check(public.has_org_role(organization_id,array['owner','admin','recruiter']::public.member_role[]));
create policy "Admins can delete candidates" on public.candidates for delete to authenticated using(public.has_org_role(organization_id,array['owner','admin']::public.member_role[]));
create policy "Members can view applications" on public.applications for select to authenticated using(public.is_org_member(organization_id));
create policy "Recruiters can manage applications" on public.applications for all to authenticated using(public.has_org_role(organization_id,array['owner','admin','recruiter']::public.member_role[])) with check(public.has_org_role(organization_id,array['owner','admin','recruiter']::public.member_role[]) and exists(select 1 from public.jobs j where j.id=job_id and j.organization_id=applications.organization_id) and exists(select 1 from public.candidates c where c.id=candidate_id and c.organization_id=applications.organization_id));
create policy "Members can view activity" on public.activity_events for select to authenticated using(public.is_org_member(organization_id));
create policy "Members can add activity" on public.activity_events for insert to authenticated with check(public.is_org_member(organization_id) and actor_id=(select auth.uid()));
grant execute on function public.is_org_member(uuid) to authenticated;
grant execute on function public.has_org_role(uuid,public.member_role[]) to authenticated;
grant execute on function public.create_organization(text) to authenticated;
